def apply(conn):
    for orig, tr in DECK_I18N.items():
        conn.execute(
            "UPDATE decks SET name=?, name_en=?, name_uz=?, description=?, "
            "description_en=?, description_uz=? "
            "WHERE name=? AND (name_en IS NULL OR name_en='')",
            (tr['name'], tr['name_en'], tr['name_uz'], tr['description'],
             tr['description_en'], tr['description_uz'], orig),
        )
    conn.commit()
